            accept: [['\\b(should|must|need to|ought to)\\b'], ['\\bpay|fund|support|spend|invest|help'], ['where|when|\\bif\\b|local|communit|ask|want'], ['widely spoken|common|shared|bilingual|two languages|both|\\btoo\\b|as well|also']],
